use semio_framework_value_control_contract::*;
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"fixture action or reply changed")}
use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};

trait WorkContext:Send{
 type Context<'a,'b>:Send where 'b:'a;
 fn validate<'a,'b>(context:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a;
 fn source<'a,'b>(context:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a;
}
struct NeutralWorkContext;
impl WorkContext for NeutralWorkContext{
 type Context<'a,'b>=() where 'b:'a;
 fn validate<'a,'b>(_:&())->Result<(),ValueError> where 'b:'a{Ok(())}
 fn source<'a,'b>(_:&())->Option<OriginalSourceTurnIdentity> where 'b:'a{None}
}
struct TurnWorkContext;
impl WorkContext for TurnWorkContext{
 type Context<'a,'b>=&'a OriginalSourceTurn where 'b:'a;
 fn validate<'a,'b>(_:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{Ok(())}
 fn source<'a,'b>(context:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(context.identity())}
}
struct SourceWorkContext;
impl WorkContext for SourceWorkContext{
 type Context<'a,'b>=(&'a OriginalSourceTurnIssuer,&'a OriginalSourceTurn) where 'b:'a;
 fn validate<'a,'b>(context:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{context.0.validate(context.1).map_err(Into::into)}
 fn source<'a,'b>(context:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(context.1.identity())}
}
struct OptionalWorkContext;
impl WorkContext for OptionalWorkContext{
 type Context<'a,'b>=Option<(&'a OriginalSourceTurnIssuer,&'a OriginalSourceTurn)> where 'b:'a;
 fn validate<'a,'b>(context:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if let Some(context)=context{SourceWorkContext::validate(context)?}Ok(())}
 fn source<'a,'b>(context:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{context.map(|(_,turn)|turn.identity())}
}
struct FixtureWork<C>{stock:u128,context:std::marker::PhantomData<C>}
impl<C> FixtureWork<C>{fn new(stock:u128)->Self{Self{stock,context:std::marker::PhantomData}}}
impl<C:WorkContext> OriginalWorkRecipient for FixtureWork<C>{
 type Context<'a,'b>=C::Context<'a,'b> where 'b:'a;
 fn validate_context<'a,'b>(&self,context:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{C::validate(context)}
 fn source_turn<'a,'b>(&self,context:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{C::source(context)}
 fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,quote:OriginalWorkQuote<'r>,_:u64,additional:u64)->OriginalWorkQuoteComplete<'r> where 'b:'a{quote.complete(Ok(u128::from(additional)<=self.stock))}
 fn settle_partial<'r,'a,'b>(&mut self,context:&mut Self::Context<'a,'b>,check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{C::validate(context).expect("actual fixture Source");self.stock=self.stock.checked_sub(check.delta()).expect("finite original Work stock");check.complete(Ok(()))}
 fn recover_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{check.pending()}
}


struct FixtureProducer<C,T>{payload:T,source:Option<OriginalSourceTurnIdentity>,pending_first:bool,receives:usize,context:std::marker::PhantomData<C>}
impl<C,T> FixtureProducer<C,T>{fn new(payload:T,source:Option<OriginalSourceTurnIdentity>,pending_first:bool)->Self{Self{payload,source,pending_first,receives:0,context:std::marker::PhantomData}}}
impl<C:WorkContext,T> OriginalEffectProducer for FixtureProducer<C,T>{
 type Output=();type Failure=ValueError;type Context<'a,'b>=C::Context<'a,'b> where 'b:'a;
 fn validate_context<'a,'b>(&self,context:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{C::validate(context)?;if C::source(context)!=self.source{return Err(invalid())}Ok(())}
 fn source_turn<'a,'b>(&self,context:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{C::source(context)}
 fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,(),ValueError>)->Result<OriginalEffectReplyComplete<'r,(),ValueError>,ValueError> where 'b:'a{self.receives+=1;assert!(effect.performed(1)?);Ok(if self.pending_first&&self.receives==1{reply.pending()}else{reply.complete(Ok(()))})}
 fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,(),ValueError>)->Result<OriginalEffectReplyComplete<'r,(),ValueError>,ValueError> where 'b:'a{assert!(effect.performed(1)?);Ok(reply.complete(Ok(())))}
}

#[test]
fn effect_producer_preserves_actual_reply_and_work_across_unwind(){

 type Work=FixtureWork<TurnWorkContext>;
 struct Actual{source:OriginalSourceTurnIdentity,calls:usize,error:Option<ValueError>,route:Option<OriginalEffectInvocationIdentity>}
 impl OriginalEffectProducer for Actual{type Output=();type Failure=ValueError;type Context<'a,'b>=&'a OriginalSourceTurn where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.identity()==self.source{Ok(())}else{Err(invalid())}}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.identity())}fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,(),ValueError>)->Result<OriginalEffectReplyComplete<'r,(),ValueError>,ValueError> where 'b:'a{self.calls+=1;let identity=effect.invocation().expect("actual original callback").identity();let mut scoped=reply.scope(&mut self.route,identity)?;assert!(effect.performed(1).unwrap());let _reply=scoped.borrow()?.complete(Err(self.error.take().unwrap()));panic!("original producer after its reply")}fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,(),ValueError>)->Result<OriginalEffectReplyComplete<'r,(),ValueError>,ValueError> where 'b:'a{Ok(reply.pending())}}
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let foreign=issuer.issue().unwrap();let error=ValueError::new(ValueRefusalKind::Canceled,"original producer error".to_owned());let pointer=error.message.as_ptr();let mut producer=OriginalEffectAuthority::new(Actual{source:turn.identity(),calls:0,error:Some(error),route:None});let mut payer=OriginalWorkAuthority::new(Work::new(3));let(mut action,mut receipt,mut proof,mut producer_action)=(None,None,None,None);payer.with_loan(&mut &turn,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let mut actual=None;let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let mut effect=RetainedAllocationEffect::new(Default::default(),1,&mut actual,receipt.as_mut().unwrap());producer.drive(&mut &turn,&mut effect,&mut producer_action).unwrap()}));assert!(interrupted.is_err());assert_eq!(producer_action.as_ref().unwrap().recorded_reply().unwrap().as_ref().unwrap_err().message.as_ptr(),pointer);work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial_output=None;assert!(work.settle_partial_for_action_into(action,&mut partial_output).unwrap());assert_eq!(partial_output.take().unwrap().delta(),1);work.issue_performed_for_action(action,&mut receipt).unwrap();{let mut effect=RetainedAllocationEffect::new(Default::default(),1,&mut actual,receipt.as_mut().unwrap());assert!(producer.drive(&mut &foreign,&mut effect,&mut producer_action).is_err());assert_eq!(producer.callback_mode(&&turn,&effect,producer_action.as_ref()).unwrap(),OriginalEffectCallbackMode::Recorded);assert!(producer.drive(&mut &turn,&mut effect,&mut producer_action).unwrap());let mut output=None;assert!(producer.copy_success_into(&&turn,producer_action.as_mut().unwrap(),&mut output,&mut effect).result.is_err());assert!(output.is_none());assert_eq!(producer_action.as_ref().unwrap().recorded_reply().unwrap().as_ref().unwrap_err().message.as_ptr(),pointer)}assert!(producer.inspect(|original|original.route.is_none()),"recorded completion must clear invocation before producer unwind");work.claim_performed_for_action(action,&mut receipt).unwrap();assert!(work.commit_for_action(1,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap();assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let demand=OriginalEffectAuthority::<Actual>::transfer_reply_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_depth:demand.depth,..Default::default()};let mut child=None;{let mut effect=RetainedAllocationEffect::new(Default::default(),1,&mut actual,receipt.as_mut().unwrap());assert!(producer.transfer_reply_into(&&turn,&mut producer_action,&mut child,&mut effect).result.unwrap().is_none());assert_eq!(producer_action.as_ref().unwrap().recorded_reply().unwrap().as_ref().unwrap_err().message.as_ptr(),pointer)}{let mut foreign_payer=OriginalWorkAuthority::new(Work::new(1));foreign_payer.with_loan(&mut &turn,|foreign_loan|{let mut foreign_loan=foreign_loan.reborrow();let mut foreign_work=OriginalWork::empty();foreign_work.recipient=Some(&mut foreign_loan);let(mut foreign_action,mut foreign_receipt,mut foreign_actual)=(None,None,None);assert_eq!(foreign_work.prepare_for_action(1,&mut foreign_action).unwrap(),Some(true));foreign_work.issue_performed_for_action(foreign_action,&mut foreign_receipt).unwrap();{let mut effect=RetainedAllocationEffect::new(grant,1,&mut foreign_actual,foreign_receipt.as_mut().unwrap());assert!(producer.transfer_reply_into(&&turn,&mut producer_action,&mut child,&mut effect).result.is_err());assert!(child.is_none());assert_eq!(producer_action.as_ref().unwrap().recorded_reply().unwrap().as_ref().unwrap_err().message.as_ptr(),pointer)}foreign_work.claim_performed_for_action(foreign_action,&mut foreign_receipt).unwrap();foreign_work.cancel_for_action(&mut foreign_action).unwrap()}).unwrap();assert!(!foreign_payer.has_live_actions());let mut effect=RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());assert!(producer.transfer_reply_into(&&foreign,&mut producer_action,&mut child,&mut effect).result.is_err());let mut occupied=Some(Ok(()));assert!(producer.transfer_reply_into(&&turn,&mut producer_action,&mut occupied,&mut effect).result.is_err());let payout=producer.transfer_reply_into(&&turn,&mut producer_action,&mut child,&mut effect);assert_eq!(payout.work,1);assert_eq!(payout.result.unwrap().unwrap().copied_bytes,demand.copy_bytes)}let error=child.take().unwrap().unwrap_err();assert_eq!(error.message.as_ptr(),pointer);assert!(producer_action.is_none());work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert_eq!(partial.take().unwrap().delta(),1);assert!(work.commit_for_action(1,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}).unwrap();assert_eq!(producer.into_producer().ok().unwrap().calls,1);assert!(!payer.has_live_actions())
}

#[test]
fn unbound_effect_authority_transfers_its_actual_producer_without_dropping_it(){

 struct Quiet(Arc<AtomicUsize>);impl Drop for Quiet{fn drop(&mut self){self.0.fetch_add(1,Ordering::Relaxed);}}
 
 let drops=Arc::new(AtomicUsize::new(0));let owner=OriginalEffectAuthority::new(FixtureProducer::<NeutralWorkContext,_>::new(Quiet(drops.clone()),None,false));assert!(!owner.has_pending_action());assert_eq!(drops.load(Ordering::Relaxed),0);let producer=owner.into_producer().ok().unwrap();assert_eq!(drops.load(Ordering::Relaxed),0);drop(producer);assert_eq!(drops.load(Ordering::Relaxed),1)
}

#[test]
fn effect_producer_requires_its_actual_bound_work_source(){

 type Context<'a>=Option<(&'a OriginalSourceTurnIssuer,&'a OriginalSourceTurn)>;
 type Work=FixtureWork<OptionalWorkContext>;
 type Producer=FixtureProducer<OptionalWorkContext,()>;
 let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🏭️producer/🧪️tests/effect-source.json")).unwrap();let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let other=issuer.issue().unwrap();for row in law.as_array().unwrap(){let producer_bound=row["producer"].as_bool().unwrap();let payer_bound=row["payer"].as_bool().unwrap();let same=row["same"].as_bool().unwrap();let accepted=row["accepted"].as_bool().unwrap();let mut producer_context=producer_bound.then_some((&issuer,&turn));let mut payer_context=payer_bound.then_some((&issuer,if same{&turn}else{&other}));let mut producer=OriginalEffectAuthority::new(Producer::new((),producer_context.map(|(_,turn)|turn.identity()),false));let mut payer=OriginalWorkAuthority::new(Work::new(3));payer.with_loan(&mut payer_context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let(mut action,mut receipt,mut actual,mut producer_action)=(None,None,None,None);assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();{let mut effect=RetainedAllocationEffect::new(Default::default(),1,&mut actual,receipt.as_mut().unwrap());assert_eq!(producer.callback_mode(&producer_context,&effect,None).is_ok(),accepted);let result=producer.drive(&mut producer_context,&mut effect,&mut producer_action);assert_eq!(result.is_ok(),accepted);if accepted{assert!(result.unwrap());let mut output=None;assert!(producer_action.as_mut().unwrap().transfer_reply(&mut output).unwrap());assert!(output.unwrap().is_ok());producer.finish(&mut producer_action).unwrap()}}work.claim_performed_for_action(action,&mut receipt).unwrap();if accepted{let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());let total=partial.take().unwrap().total();let mut proof=None;assert!(work.commit_for_action(total,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}else{assert!(producer_action.is_none());work.cancel_for_action(&mut action).unwrap()}}).unwrap();assert!(producer.into_producer().is_ok());assert!(!payer.has_live_actions())}
}

#[test]
fn paid_effect_producer_transfer_retains_the_same_idle_owner(){

 type Work=FixtureWork<NeutralWorkContext>;
 type Producer=FixtureProducer<NeutralWorkContext,Box<u8>>;
 let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🏭️producer/🧪️tests/effect-transfer.json")).unwrap();assert_eq!(law[0]["accepted"],true);assert_eq!(law[1]["accepted"],false);let mut producer=Some(OriginalEffectAuthority::new(Producer::new(Box::new(7),None,true)));let pointer=std::ptr::from_ref(&*producer.as_ref().unwrap().producer().payload);let mut payer=OriginalWorkAuthority::new(Work::new(3));payer.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let(mut action,mut receipt,mut marker,mut invocation,mut output)=(None,None,None,None,None);assert_eq!(work.prepare_for_action(3,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();{let demand=OriginalEffectAuthority::<Producer>::producer_transfer_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_depth:demand.depth,..Default::default()};let mut effect=RetainedAllocationEffect::new(grant,3,&mut marker,receipt.as_mut().unwrap());assert!(!producer.as_mut().unwrap().drive(&mut (),&mut effect,&mut invocation).unwrap());let turn=OriginalEffectAuthority::transfer_producer(&mut producer,&(),&mut output,&mut effect);assert!(turn.result.is_err());assert!(output.is_none()&&producer.is_some());assert!(producer.as_mut().unwrap().drive(&mut (),&mut effect,&mut invocation).unwrap());let mut result=None;assert!(invocation.as_mut().unwrap().transfer_reply(&mut result).unwrap());assert!(result.unwrap().is_ok());producer.as_mut().unwrap().finish(&mut invocation).unwrap();{let remaining=effect.remaining_work_units().unwrap();let mut denied=effect.reborrow(RetainedCloneGrant{maximum_items:0,..grant},remaining).unwrap();let turn=OriginalEffectAuthority::transfer_producer(&mut producer,&(),&mut output,&mut denied);assert!(turn.result.unwrap().is_none());assert_eq!(turn.work,0)}let turn=OriginalEffectAuthority::transfer_producer(&mut producer,&(),&mut output,&mut effect);assert!(turn.result.unwrap().is_some());assert_eq!(turn.work,1);assert!(producer.is_none());assert_eq!(std::ptr::from_ref(&*output.as_ref().unwrap().payload),pointer)}work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert_eq!(partial.take().unwrap().total(),3);let mut proof=None;assert!(work.commit_for_action(3,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap();drop(output.take())}).unwrap();assert!(!payer.has_live_actions());
}

#[test]
fn invocation_witness_preserves_actual_action_across_pending_and_nested_reborrow(){
 
 type Work=FixtureWork<SourceWorkContext>;
 struct Producer{source:OriginalSourceTurnIdentity,seen:[Option<(OriginalEffectInvocationIdentity,OriginalEffectCallbackMode)>;3],calls:usize}
 impl Producer{
  fn observe(&mut self,effect:&mut RetainedAllocationEffect<'_>,mode:OriginalEffectCallbackMode)->Result<(),ValueError>{
   let invocation=effect.invocation().expect("actual producer invocation");assert_eq!(invocation.mode(),mode);assert_eq!(invocation.source_turn(),Some(self.source));let identity=invocation.identity();let remaining=effect.remaining_work_units()?;let grant=effect.grant();
   {let nested=effect.reborrow(grant,remaining)?;assert_eq!(nested.invocation().unwrap().identity(),identity);assert_eq!(nested.invocation().unwrap().mode(),mode)}
   self.seen[self.calls]=Some((identity,mode));self.calls+=1;assert!(effect.performed(1)?);Ok(())
  }
 }
 impl OriginalEffectProducer for Producer{
  type Output=();type Failure=ValueError;type Context<'a,'b>=(&'a OriginalSourceTurnIssuer,&'a OriginalSourceTurn) where 'b:'a;
  fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{c.0.validate(c.1).map_err(ValueError::from)?;if c.1.identity()!=self.source{return Err(invalid())}Ok(())}
  fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.1.identity())}
  fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,(),ValueError>)->Result<OriginalEffectReplyComplete<'r,(),ValueError>,ValueError> where 'b:'a{self.observe(effect,OriginalEffectCallbackMode::Receive)?;Ok(if self.calls==1{reply.pending()}else{reply.complete(Ok(()))})}
  fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,(),ValueError>)->Result<OriginalEffectReplyComplete<'r,(),ValueError>,ValueError> where 'b:'a{self.observe(effect,OriginalEffectCallbackMode::Recover)?;Ok(reply.complete(Ok(())))}
 }
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🏭️producer/🧪️tests/invocation.json")).unwrap();
 let issuer=OriginalSourceTurnIssuer::new();let source=issuer.issue().unwrap();let mut context=(&issuer,&source);let mut payer=OriginalWorkAuthority::new(Work::new(u128::from(fixture["fuel"].as_u64().unwrap())));let mut producer=OriginalEffectAuthority::new(Producer{source:source.identity(),seen:[None;3],calls:0});
 payer.with_loan(&mut context,|loan|{
  let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);
  for ceiling in fixture["actionCeilings"].as_array().unwrap(){
   let ceiling=ceiling.as_u64().unwrap();let(mut action,mut receipt,mut proof,mut marker,mut invocation)=(None,None,None,None,None);assert_eq!(work.prepare_for_action(ceiling,&mut action).unwrap(),Some(true));let mut complete=false;
   while !complete{
    work.issue_performed_for_action(action,&mut receipt).unwrap();
    {let mut effect=RetainedAllocationEffect::new(Default::default(),ceiling,&mut marker,receipt.as_mut().unwrap());assert!(effect.invocation().is_none());complete=producer.drive(&mut (&issuer,&source),&mut effect,&mut invocation).unwrap();assert!(effect.invocation().is_none())}
    work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());let partial=partial.take().unwrap();assert_eq!(partial.delta(),1);assert!(partial.admitted());assert!(partial.source_refusal().is_none());if !complete{assert!(producer.finish(&mut invocation).is_err())}
   }
   let mut output=None;assert!(invocation.as_mut().unwrap().transfer_reply(&mut output).unwrap());assert!(output.take().unwrap().is_ok());producer.finish(&mut invocation).unwrap();assert!(work.commit_for_action(u128::from(ceiling),action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()
  }
 }).unwrap();
 let producer=producer.into_producer().ok().unwrap();assert_eq!(producer.calls,3);let first=producer.seen[0].unwrap();let second=producer.seen[1].unwrap();let third=producer.seen[2].unwrap();assert_eq!(first.0,second.0);assert_ne!(second.0,third.0);assert_eq!([first.1,second.1,third.1],[OriginalEffectCallbackMode::Receive,OriginalEffectCallbackMode::Recover,OriginalEffectCallbackMode::Receive]);assert_eq!(payer.inspect(|work|work.stock),0);assert!(!payer.has_live_actions())
}

#[test]
fn before_effect_birth_retains_actual_work_and_rejects_foreign_or_active_ports(){
 
 type Context<'a>=Option<(&'a OriginalSourceTurnIssuer,&'a OriginalSourceTurn)>;
 type Work=FixtureWork<OptionalWorkContext>;
 struct Producer{source:Option<OriginalSourceTurnIdentity>,input:Option<u64>,output:Option<u64>,action:Option<OriginalWorkActionIdentity>,receipt:Option<OriginalWorkPerformedReceipt>,claim:Option<Result<u128,ValueError>>,partial:Option<OriginalWorkPartialOutcome>,proof:Option<OriginalWorkActionProof>}
 impl OriginalEffectProducer for Producer{
  type Output=RetainedCloneStep;type Failure=ValueError;type Context<'a,'b>=Context<'a> where 'b:'a;
  fn validate_context<'a,'b>(&self,c:&Context<'a>)->Result<(),ValueError> where 'b:'a{if let Some((issuer,turn))=c{issuer.validate(turn).map_err(ValueError::from)?}if c.map(|(_,turn)|turn.identity())!=self.source{return Err(invalid())}Ok(())}
  fn source_turn<'a,'b>(&self,c:&Context<'a>)->Option<OriginalSourceTurnIdentity> where 'b:'a{c.map(|(_,turn)|turn.identity())}
  fn receive<'r,'a,'b>(&mut self,_:&mut Context<'a>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError> where 'b:'a{Ok(reply.pending())}
  fn recover<'r,'a,'b>(&mut self,_:&mut Context<'a>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError> where 'b:'a{Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}
 }
 impl OriginalEffectBirthProducer for Producer{
  type Original<'loan>=OriginalWorkBorrow<'loan>;
  fn requires_original_birth(&self)->bool{self.input.is_some()||self.action.is_some()}
  fn close_original_birth<'a,'b,'loan>(&mut self,_:&mut Context<'a>,original:&mut Self::Original<'loan>,grant:RetainedCloneGrant)->RetainedWorkPoll<RetainedCloneStep,ValueError> where 'b:'a{
   let mut work=original.original_work();
   if self.input.is_some(){
    assert_eq!(work.prepare(1,&mut self.action).unwrap(),Some(true));
    {let mut scope=work.performed_scope(self.action,&mut self.receipt,&mut self.claim).unwrap();let mut actual=None;let mut effect=scope.effect(grant,1,&mut actual).unwrap();assert!(effect.performed(1).unwrap());self.output=self.input.take();assert_eq!(*effect.actual(),None)}
    assert_eq!(self.claim.take().unwrap().unwrap(),1);return RetainedWorkPoll::Pending{work:1}
   }
   assert!(work.settle_partial_into(self.action,&mut self.partial).unwrap());let partial=self.partial.take().unwrap();assert_eq!(partial.delta(),1);assert!(partial.source_refusal().is_none());assert!(work.commit(partial.total(),self.action,&mut self.proof).unwrap());work.finish(&mut self.proof,&mut self.action).unwrap();
   RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})
  }
 }
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🏭️producer/🧪️tests/birth.json")).unwrap();let issuer=OriginalSourceTurnIssuer::new();let source=issuer.issue().unwrap();let other=issuer.issue().unwrap();
 for row in fixture["cases"].as_array().unwrap(){
  let mut producer_context=row["producer"].as_bool().unwrap().then_some((&issuer,&source));let mut work_context=row["payer"].as_bool().unwrap().then_some((&issuer,if row["same"].as_bool().unwrap(){&source}else{&other}));let active=row["active"].as_bool().unwrap();let accepted=row["accepted"].as_bool().unwrap();let value=fixture["value"].as_u64().unwrap();let mut producer=OriginalEffectAuthority::new(Producer{source:producer_context.map(|(_,turn)|turn.identity()),input:Some(value),output:None,action:None,receipt:None,claim:None,partial:None,proof:None});let mut payer=OriginalWorkAuthority::new(Work::new(u128::from(fixture["fuel"].as_u64().unwrap())));
  payer.with_loan(&mut work_context,|loan|{
   let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let(mut normal,mut receipt,mut actual,mut invocation)=(None,None,None,None);
   if active{assert_eq!(work.prepare_for_action(1,&mut normal).unwrap(),Some(true));work.issue_performed_for_action(normal,&mut receipt).unwrap();{let mut effect=RetainedAllocationEffect::new(Default::default(),1,&mut actual,receipt.as_mut().unwrap());assert!(!producer.drive(&mut producer_context,&mut effect,&mut invocation).unwrap())}work.claim_performed_for_action(normal,&mut receipt).unwrap()}
   {let mut original=OriginalWorkBorrow::new(&mut work);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:2*std::mem::size_of::<Option<u64>>()+std::mem::size_of::<u64>(),maximum_depth:1,..Default::default()};let first=producer.drive_original_birth(&mut producer_context,&mut original,grant);assert_eq!(first.is_ok(),accepted);
    if accepted{assert!(matches!(first.unwrap(),RetainedWorkPoll::Pending{work:1}));assert!(producer.producer().requires_original_birth());assert_eq!(producer.producer().output,Some(value));assert!(matches!(producer.drive_original_birth(&mut producer_context,&mut original,grant).unwrap(),RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(_),work:0})));assert!(!producer.producer().requires_original_birth())}else{assert_eq!(producer.producer().input,Some(value));assert!(producer.producer().output.is_none())}
   }
   if active{work.issue_performed_for_action(normal,&mut receipt).unwrap();{let mut effect=RetainedAllocationEffect::new(Default::default(),1,&mut actual,receipt.as_mut().unwrap());assert!(producer.drive(&mut producer_context,&mut effect,&mut invocation).unwrap())}work.claim_performed_for_action(normal,&mut receipt).unwrap();let mut output=None;assert!(invocation.as_mut().unwrap().transfer_reply(&mut output).unwrap());producer.finish(&mut invocation).unwrap();work.cancel_for_action(&mut normal).unwrap()}
  }).unwrap();assert_eq!(payer.inspect(|work|work.stock),u128::from(!accepted));assert!(!payer.has_live_actions());assert!(producer.into_producer().is_ok())
 }
}

#[test]
fn recorded_copy_success_uses_same_work_and_preserves_unfunded_reply(){
 type Work=FixtureWork<NeutralWorkContext>;type Producer=FixtureProducer<NeutralWorkContext,()>;let mut producer=OriginalEffectAuthority::new(Producer::new((),None,false));let mut payer=OriginalWorkAuthority::new(Work::new(3));let(mut first,mut receipt,mut proof,mut original)=(None,None,None,None);payer.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);assert_eq!(work.prepare_for_action(1,&mut first).unwrap(),Some(true));work.issue_performed_for_action(first,&mut receipt).unwrap();let mut actual=None;{let mut effect=RetainedAllocationEffect::new(Default::default(),1,&mut actual,receipt.as_mut().unwrap());assert!(producer.drive(&mut (),&mut effect,&mut original).unwrap())}work.claim_performed_for_action(first,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(first,&mut partial).unwrap());assert_eq!(partial.take().unwrap().delta(),1);assert!(work.commit_for_action(1,first,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut first).unwrap();assert_eq!(work.prepare_for_action(1,&mut first).unwrap(),Some(true));work.issue_performed_for_action(first,&mut receipt).unwrap();let demand=OriginalEffectAuthority::<Producer>::copy_success_demand().unwrap();let mut output=None;{let mut effect=RetainedAllocationEffect::new(Default::default(),1,&mut actual,receipt.as_mut().unwrap());assert!(producer.copy_success_into(&(),original.as_mut().unwrap(),&mut output,&mut effect).result.unwrap().is_none());assert!(output.is_none());assert!(original.as_ref().unwrap().recorded_reply().unwrap().is_ok())}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_depth:demand.depth,..Default::default()};output=Some(());{let mut effect=RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());assert!(producer.copy_success_into(&(),original.as_mut().unwrap(),&mut output,&mut effect).result.is_err());assert_eq!(output,Some(()));let moved=producer.replace_copy_success_into(&(),original.as_mut().unwrap(),&mut output,&mut effect);assert_eq!(moved.work,1);assert_eq!(moved.result.unwrap().unwrap().copied_bytes,demand.copy_bytes);assert_eq!(output,Some(()));assert!(original.as_ref().unwrap().recorded_reply().is_none())}producer.finish(&mut original).unwrap();work.claim_performed_for_action(first,&mut receipt).unwrap();assert!(work.settle_partial_for_action_into(first,&mut partial).unwrap());assert_eq!(partial.take().unwrap().delta(),1);assert!(work.commit_for_action(1,first,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut first).unwrap()}).unwrap();let _=producer.into_producer().ok().unwrap();assert!(!payer.has_live_actions())
}

#[test]
fn forward_metadata_stays_with_actual_marked_action_through_recorded_reply_and_post_unwind(){
 struct Physical{source:OriginalSourceTurnIdentity,posts:usize,interrupt:bool,submitted:RetainedCloneProgress}
 impl OriginalConstructionRecipient for Physical{type Context<'a,'b>=(&'a OriginalSourceTurnIssuer,&'a OriginalSourceTurn)where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{c.0.validate(c.1).map_err(Into::into)}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.1.identity())}fn grant<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:OriginalConstructionGrant<'r>)->OriginalConstructionGrantComplete<'r>where 'b:'a{let d=reply.demand();reply.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}))}fn accept<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,reply:OriginalConstructionAccept<'r>)->OriginalConstructionAcceptComplete<'r>where 'b:'a{assert_eq!(c.1.identity(),self.source);self.posts+=1;self.submitted=self.submitted.checked_add(reply.progress()).unwrap();let complete=reply.complete(Ok(()));if self.interrupt{self.interrupt=false;panic!("actual recorded physical Post unwind")}complete}fn submitted<'a,'b>(&self,_:&Self::Context<'a,'b>)->RetainedCloneProgress where 'b:'a{self.submitted}}
 struct Producer{source:OriginalSourceTurnIdentity,error:Option<ValueError>,pointer:usize,receives:usize,recovers:usize,route:Option<OriginalEffectInvocationIdentity>}
 impl OriginalEffectProducer for Producer{type Output=();type Failure=ValueError;type Context<'a,'b>=(&'a OriginalSourceTurnIssuer,&'a OriginalSourceTurn)where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{c.0.validate(c.1).map_err(Into::into)}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{assert_eq!(c.1.identity(),self.source);Some(c.1.identity())}fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,(),ValueError>)->Result<OriginalEffectReplyComplete<'r,(),ValueError>,ValueError>where 'b:'a{self.receives+=1;assert!(effect.record_forward_metadata(2*std::mem::size_of::<Option<OriginalEffectInvocationIdentity>>())?);assert!(effect.performed(1)?);let(pointer,attempts)=semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||{*effect.actual()=Some(0);unsafe{std::alloc::alloc(std::alloc::Layout::new::<u8>())}});assert!(pointer.is_null());assert_eq!(attempts,1);let identity=effect.invocation().ok_or_else(||ValueError::invariant("original invocation absent"))?.identity();let mut scope=reply.scope(&mut self.route,identity)?;drop(scope.borrow()?.complete(Err(self.error.take().unwrap())));panic!("actual reply recorded before unwind")}fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,(),ValueError>)->Result<OriginalEffectReplyComplete<'r,(),ValueError>,ValueError>where 'b:'a{self.recovers+=1;Ok(reply.pending())}}
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🏭️producer/🧪️tests/borrowed-forward.json")).unwrap();let source=OriginalSourceTurnIssuer::new();let turn=source.issue().unwrap();let mut payer=OriginalWorkAuthority::new(FixtureWork::<SourceWorkContext>::new(8));let mut physical=OriginalConstructionAuthority::new(Physical{source:turn.identity(),posts:0,interrupt:true,submitted:Default::default()});let error=ValueError::new(ValueRefusalKind::InvalidValue,String::from("retained actual source error"));let pointer=error.message.as_ptr()as usize;let mut producer=OriginalEffectAuthority::new(Producer{source:turn.identity(),error:Some(error),pointer,receives:0,recovers:0,route:None});let mut payer_context=(&source,&turn);let mut physical_context=(&source,&turn);let mut producer_context=(&source,&turn);
 payer.with_loan(&mut payer_context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);physical.with_loan(&mut physical_context,|physical|{let(mut work_action,mut receipt,mut proof,mut action,mut construction)=(None,None,None,None,None);assert_eq!(work.prepare_for_action(2,&mut work_action).unwrap(),Some(true));let demand=RetirementDemand{copy_bytes:2*std::mem::size_of::<Option<OriginalEffectInvocationIdentity>>(),capacity_bytes:1,depth:1,..Default::default()};physical.begin(demand,&mut construction,&OriginalWorkBorrow::new(&mut work)).unwrap();physical.quote(construction.as_mut().unwrap()).unwrap();let grant=physical.recover_grant(construction.as_mut().unwrap()).unwrap().unwrap().unwrap();let foreign_turn=source.issue().unwrap();let mut foreign_context=(&source,&foreign_turn);let mut foreign_payer=OriginalWorkAuthority::new(FixtureWork::<SourceWorkContext>::new(1));foreign_payer.with_loan(&mut foreign_context,|foreign_loan|{let mut foreign_loan=foreign_loan.reborrow();let mut foreign=OriginalWork::empty();foreign.recipient=Some(&mut foreign_loan);let(mut foreign_action,mut foreign_receipt)=(None,None);assert_eq!(foreign.prepare_for_action(1,&mut foreign_action).unwrap(),Some(true));foreign.issue_performed_for_action(foreign_action,&mut foreign_receipt).unwrap();assert!(physical.effect_for_action(construction.as_mut().unwrap(),1,foreign_receipt.as_mut().unwrap()).is_err());assert!(construction.as_ref().unwrap().actual().is_none());foreign.claim_performed_for_action(foreign_action,&mut foreign_receipt).unwrap();foreign.cancel_for_action(&mut foreign_action).unwrap()}).unwrap();assert!(!foreign_payer.has_live_actions());let mut sibling=None;physical.begin(demand,&mut sibling,&OriginalWorkBorrow::new(&mut work)).unwrap();physical.quote(sibling.as_mut().unwrap()).unwrap();physical.recover_grant(sibling.as_mut().unwrap()).unwrap().unwrap().unwrap();let sibling_identity=sibling.as_ref().unwrap().identity();let physical_identity=construction.as_ref().unwrap().identity();let effect_proof=physical.effect_proof(construction.as_ref().unwrap()).unwrap();assert_ne!(sibling_identity,physical_identity);let mut claim=None;let mut lender=OriginalWorkBorrow::new(&mut work);let mut scope=lender.performed_scope(work_action,&mut receipt,&mut claim).unwrap();{let mut effect=scope.construction_effect(physical,sibling.as_mut().unwrap(),2).unwrap();assert_eq!(effect.construction_action(),Some(sibling_identity));assert_eq!(effect_proof.matches_effect(&effect),fixture["siblingProofAccepted"].as_bool().unwrap());assert_eq!(effect.reborrow(grant,2).unwrap().construction_action(),Some(sibling_identity))}assert!(construction.as_ref().unwrap().actual().is_none());physical.cancel(sibling.as_mut().unwrap(),false,Default::default(),None).unwrap();physical.finish(&mut sibling).unwrap();let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let mut effect=scope.construction_effect(physical,construction.as_mut().unwrap(),2).unwrap();assert_eq!(effect.construction_action(),Some(physical_identity));assert_eq!(effect_proof.matches_effect(&effect),fixture["matchingProofAccepted"].as_bool().unwrap());producer.drive(&mut producer_context,&mut effect,&mut action).unwrap()}));assert!(interrupted.is_err());let mut marker=construction.as_ref().unwrap().actual();assert_eq!(marker,Some(fixture["allocationMarker"].as_u64().unwrap()as usize));let pending=action.as_ref().unwrap();assert_eq!(pending.recorded_reply().unwrap().as_ref().unwrap_err().message.as_ptr()as usize,pointer);assert_eq!(pending.forward_progress().copied_bytes,demand.copy_bytes);drop(scope);drop(lender);assert_eq!(claim.take().unwrap().unwrap(),2);let mut partial=None;assert!(work.settle_partial_for_action_into(work_action,&mut partial).unwrap());assert_eq!(partial.take().unwrap().delta(),2);let progress=action.as_ref().unwrap().forward_progress();assert!(physical.cancel(construction.as_mut().unwrap(),false,Default::default(),None).is_err());assert!(physical.post(construction.as_mut().unwrap(),progress,None).is_err());assert_eq!(construction.as_ref().unwrap().actual(),marker);let posted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||physical.post(construction.as_mut().unwrap(),progress,marker)));assert!(posted.is_err());assert_eq!(physical.recover_accept(construction.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));physical.finish_accepted(&mut construction).unwrap();work.issue_performed_for_action(work_action,&mut receipt).unwrap();{let mut effect=RetainedAllocationEffect::new(grant,1,&mut marker,receipt.as_mut().unwrap());assert!(producer.drive(&mut producer_context,&mut effect,&mut action).unwrap())}work.claim_performed_for_action(work_action,&mut receipt).unwrap();assert_eq!(producer.inspect(|p|(p.receives,p.recovers,p.pointer)),(fixture["receiveCalls"].as_u64().unwrap()as usize,fixture["recoverCalls"].as_u64().unwrap()as usize,pointer));assert!(work.commit_for_action(2,work_action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut work_action).unwrap();
 let d=OriginalEffectAuthority::<Producer>::transfer_reply_demand().unwrap();assert_eq!(work.prepare_for_action(1,&mut work_action).unwrap(),Some(true));physical.begin(d,&mut construction,&OriginalWorkBorrow::new(&mut work)).unwrap();physical.quote(construction.as_mut().unwrap()).unwrap();let grant=physical.recover_grant(construction.as_mut().unwrap()).unwrap().unwrap().unwrap();work.issue_performed_for_action(work_action,&mut receipt).unwrap();let mut no_marker=None;let mut output=None;{let mut effect=RetainedAllocationEffect::new(grant,1,&mut no_marker,receipt.as_mut().unwrap());let transfer=producer.transfer_reply_into(&producer_context,&mut action,&mut output,&mut effect);assert_eq!(transfer.work,1);assert_eq!(transfer.result.unwrap().unwrap().copied_bytes,d.copy_bytes)}work.claim_performed_for_action(work_action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(work_action,&mut partial).unwrap());partial.take();assert_eq!(output.as_ref().unwrap().as_ref().unwrap_err().message.as_ptr()as usize,pointer);physical.post(construction.as_mut().unwrap(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()},None).unwrap();assert_eq!(physical.recover_accept(construction.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));physical.finish_accepted(&mut construction).unwrap();assert!(work.commit_for_action(1,work_action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut work_action).unwrap();
 let release=match &output.as_ref().unwrap().as_ref().unwrap_err().message{std::borrow::Cow::Owned(message)=>message.capacity(),_=>panic!("actual error lost owned message")};let d=RetirementDemand{copy_bytes:std::mem::size_of::<Option<Result<(),ValueError>>>(),release_bytes:release,depth:1,..Default::default()};assert_eq!(work.prepare_for_action(1,&mut work_action).unwrap(),Some(true));physical.begin(d,&mut construction,&OriginalWorkBorrow::new(&mut work)).unwrap();physical.quote(construction.as_mut().unwrap()).unwrap();let grant=physical.recover_grant(construction.as_mut().unwrap()).unwrap().unwrap().unwrap();work.issue_performed_for_action(work_action,&mut receipt).unwrap();{let mut effect=RetainedAllocationEffect::new(grant,1,&mut no_marker,receipt.as_mut().unwrap());assert!(effect.performed(1).unwrap());drop(output.take())}work.claim_performed_for_action(work_action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(work_action,&mut partial).unwrap());partial.take();physical.post(construction.as_mut().unwrap(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:release,..Default::default()},None).unwrap();assert_eq!(physical.recover_accept(construction.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));physical.finish_accepted(&mut construction).unwrap();assert!(work.commit_for_action(1,work_action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut work_action).unwrap();Ok::<_,ValueError>(())}).unwrap()}).unwrap().unwrap();assert_eq!(physical.inspect(|p|p.posts),3);assert!(!payer.has_live_actions());assert!(producer.into_producer().is_ok());}

#[test]
fn shared_lender_charges_the_same_original_receipt_across_sequential_loans(){
 let f:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🏭️producer/🧪️tests/shared-lender.json")).unwrap();let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let mut context=(&issuer,&turn);let mut payer=OriginalWorkAuthority::new(FixtureWork::<SourceWorkContext>::new(6));payer.with_loan(&mut context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let(mut action,mut receipt,mut proof,mut partial)=(None,None,None,None);assert_eq!(work.prepare_for_action(3,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();{let lender=OriginalWorkLender::new(receipt.as_mut().unwrap(),3).unwrap();let mut first=lender.loan();let mut second=lender.loan();assert_eq!(first.identity(),second.identity());assert_eq!(first.source_turn(),Some(turn.identity()));let mut marker=None;let mut effect=RetainedAllocationEffect::new(Default::default(),3,&mut marker,&mut first);assert!(effect.performed(f["first"].as_u64().unwrap()).unwrap());assert_eq!(second.observed_work(),1);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{assert!(second.performed(f["second"].as_u64().unwrap()).unwrap());panic!("actual second loan unwound")}));assert!(interrupted.is_err());assert_eq!(effect.remaining_work_units().unwrap(),0);drop(effect);assert_eq!(first.observed_work(),3)}work.claim_performed_for_action(action,&mut receipt).unwrap();assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert_eq!(partial.take().unwrap().delta(),3);assert!(work.commit_for_action(3,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap();assert_eq!(work.prepare_for_action(3,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();{let lender=OriginalWorkLender::new(receipt.as_mut().unwrap(),f["window"].as_u64().unwrap()).unwrap();let mut first=lender.loan();let mut second=lender.loan();assert!(first.performed(1).unwrap());assert_eq!(!second.performed(f["second"].as_u64().unwrap()).unwrap(),f["localOverrun"].as_bool().unwrap());assert_eq!(first.observed_work(),f["total"].as_u64().unwrap() as u128);assert!(first.remaining_work_units().is_err())}work.claim_performed_for_action(action,&mut receipt).unwrap();assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert_eq!(partial.take().unwrap().delta(),3);assert!(work.commit_for_action(3,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}).unwrap();assert!(!payer.has_live_actions());
}
